  Tool? press({
    required String letter,
    required bool shift,
    required double now,
    required Tool current,
  }) => RustLib.instance.api.crateApiCatalogToolKeysPress(
    that: this,
    letter: letter,
    shift: shift,
    now: now,
    current: current,
  );
}
